codeExample.bad:
// A "new content available" banner interrupts the user immediately and
// repeatedly, with no way to postpone or dismiss it long-term
setInterval(() => {
  showInterruptingBanner('New articles are available. Refresh now?');
}, 30000);

codeExample.good:
// The same notification, but the user can suppress it for the
// remainder of their session (non-emergency, so postponable per SC 2.2.4)
let notificationsSuppressed = getUserPreference('suppressUpdateNotifications');
setInterval(() => {
  if (!notificationsSuppressed) {
    showDismissibleBanner('New articles are available. Refresh now?', {
      onSuppress: () => { notificationsSuppressed = true; }
    });
  }
}, 30000);
